// Extract structured error details from the Error Trigger payload
const errorData = $input.first().json;

// n8n Error Trigger provides: execution.error, execution.id, workflow.name, workflow.id
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const error = execution.error || {};

// Extract the failing node info
const failingNode = error.node || {};

// Build clean error record
const result = {
  timestamp: new Date().toISOString(),
  workflow_name: workflow.name || 'unknown',
  workflow_id: workflow.id || 'unknown',
  execution_id: execution.id || 'unknown',
  error_node: failingNode.name || error.nodeName || 'unknown',
  error_message: (error.message || 'unknown').substring(0, 2000),
  error_type: error.name || error.type || 'ExecutionError',
  space: 'auto-detected',
  // Extra context for debugging
  execution_mode: execution.mode || 'unknown',
  execution_url: execution.url || '',
  node_type: failingNode.type || 'unknown',
  retry_of: execution.retryOf || null,
  raw_error_keys: Object.keys(errorData).join(',')
};

return [{json: result}];

