// Final summary for execution log
const input = $input.first().json;
const supabaseStatus = (input.statusCode === 201 || input.statusCode === 200) ? 'LOGGED' : 'LOG_FAILED';

const prevData = $node['Extract Error Details'].json;

return [{
  json: {
    status: supabaseStatus,
    workflow_name: prevData.workflow_name,
    error_node: prevData.error_node,
    error_type: prevData.error_type,
    error_message: prevData.error_message.substring(0, 200),
    logged_at: new Date().toISOString()
  }
}];
